public class GoodCode {
    public int processOrder(int a, int b, int c, int d, int e, int f) {
        int result = 0;
        result += addIfGreaterThanTen(a);
        result += addIfGreaterThanTen(b);
        result += addIfGreaterThanTen(c);
        result += addIfGreaterThanTen(d);
        result += addIfGreaterThanTen(e);
        result += addIfGreaterThanTen(f);
        return result;
    }

    private int addIfGreaterThanTen(int num) {
        return num > 10 ? num : 0;
    }
}

public class OrderProcessor {
    public int processOrder(int... numbers) {
        int result = 0;
        for (int number : numbers) {
            if (number > 10) {
                result += number;
            }
        }
        return result;
    }
}

